import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Compiler Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/compiler-pipeline.md","filePath":"architecture/compiler-pipeline.md"}`),a={name:`architecture/compiler-pipeline.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="compiler-pipeline" tabindex="-1">Compiler Pipeline <a class="header-anchor" href="#compiler-pipeline" aria-label="Permalink to “Compiler Pipeline”">​</a></h1><p>This page describes the main compilation flow from source text to native code or SIR-backed execution.</p><h2 id="end-to-end-flow" tabindex="-1">End-to-End Flow <a class="header-anchor" href="#end-to-end-flow" aria-label="Permalink to “End-to-End Flow”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source (.vx)</span></span>
<span class="line"><span>  -&gt; lexer</span></span>
<span class="line"><span>  -&gt; parser / syntax tree</span></span>
<span class="line"><span>  -&gt; HIR lowering</span></span>
<span class="line"><span>  -&gt; comptime generator discovery and canonical CTFE</span></span>
<span class="line"><span>  -&gt; sealed source/generated HIR snapshot</span></span>
<span class="line"><span>  -&gt; type inference + borrow analysis + semantic checks</span></span>
<span class="line"><span>  -&gt; typed known/residual staging</span></span>
<span class="line"><span>  -&gt; codegen selection</span></span>
<span class="line"><span>       -&gt; LLVM/native path</span></span>
<span class="line"><span>       -&gt; SIR graph path</span></span>
<span class="line"><span>  -&gt; link / subprocess execution</span></span></code></pre></div><h2 id="front-end-stages" tabindex="-1">Front-End Stages <a class="header-anchor" href="#front-end-stages" aria-label="Permalink to “Front-End Stages”">​</a></h2><h3 id="lexer" tabindex="-1">Lexer <a class="header-anchor" href="#lexer" aria-label="Permalink to “Lexer”">​</a></h3><p><code>vex-lexer</code> tokenizes source text.</p><h3 id="parser" tabindex="-1">Parser <a class="header-anchor" href="#parser" aria-label="Permalink to “Parser”">​</a></h3><p><code>vex-parser</code> constructs the syntax tree and keeps enough recovery behavior for diagnostics and tooling.</p><h3 id="syntax-layer" tabindex="-1">Syntax Layer <a class="header-anchor" href="#syntax-layer" aria-label="Permalink to “Syntax Layer”">​</a></h3><p><code>vex-syntax</code> defines the syntax node model used by the parser and later lowering passes.</p><h2 id="hir-and-semantic-analysis" tabindex="-1">HIR and Semantic Analysis <a class="header-anchor" href="#hir-and-semantic-analysis" aria-label="Permalink to “HIR and Semantic Analysis”">​</a></h2><p><code>vex-hir</code> is where syntax becomes semantically meaningful program structure.</p><p>Key responsibilities include:</p><ul><li>name resolution</li><li>type inference</li><li>pattern lowering</li><li>contract-related checks</li><li>borrow and move analysis</li><li>enum, <code>Option</code>, and <code>Result</code> behavior</li></ul><h2 id="comptime-and-expansion" tabindex="-1">Comptime and expansion <a class="header-anchor" href="#comptime-and-expansion" aria-label="Permalink to “Comptime and expansion”">​</a></h2><p>Canonical CTFE runs on HIR before backend codegen. It evaluates strict <code>#</code> boundaries and eligible ordinary <code>const fn</code> calls, expands authorized typed <code>DeclSet</code> module generators, and produces one sealed source/generated semantic snapshot for compiler, diagnostics, lint, and LSP.</p><p>Staging classifies work as known, typed residual HIR, or an error. Runtime effects and runtime-dependent values remain in the ordinary pipeline; strict compile-time consumers never receive a runtime fallback.</p><p>Generated declarations are not printed or reparsed and do not cross a separate bitcode boundary. Their typed HIR remains visible to monomorphization, VUMM, fusion, ABI lowering, and dead-code elimination.</p><p>See <a href="/docs/architecture/comptime-pipeline">Comptime Pipeline</a> for the full flow.</p><h2 id="memory-safety-analysis" tabindex="-1">Memory-Safety Analysis <a class="header-anchor" href="#memory-safety-analysis" aria-label="Permalink to “Memory-Safety Analysis”">​</a></h2><p>The repository describes the borrow system as a multi-phase analysis model. The high-level responsibilities are:</p><ol><li>immutability and <code>let</code> vs <code>let!</code> enforcement</li><li>move tracking</li><li>borrow rule validation</li><li>lifetime-oriented validation</li></ol><p>This is the part of the compiler that enforces the memory model documented in the guide.</p><h2 id="two-main-lowering-paths" tabindex="-1">Two Main Lowering Paths <a class="header-anchor" href="#two-main-lowering-paths" aria-label="Permalink to “Two Main Lowering Paths”">​</a></h2><h3 id="native-llvm-path" tabindex="-1">Native LLVM Path <a class="header-anchor" href="#native-llvm-path" aria-label="Permalink to “Native LLVM Path”">​</a></h3><p><code>vex-compiler</code> lowers checked HIR into LLVM IR and then into object code, linked executables.</p><p>This path is the default for ordinary systems code.</p><h4 id="callable-and-alias-contracts" tabindex="-1">Callable and alias contracts <a class="header-anchor" href="#callable-and-alias-contracts" aria-label="Permalink to “Callable and alias contracts”">​</a></h4><p>First-class functions and closures have one internal representation: <code>{ code, context }</code>. The context is always a valid non-null pointer; a capture-free callable uses a private zero-cost sentinel rather than a heap allocation. Direct calls, indirect calls, callable fields and error-rescue handlers share the same physical ABI decisions for hidden return storage, aggregate parameters, references, alignment and capture guarantees. Because a true indirect call has no visible declaration to inherit from, its sealed HIR function type publishes those facts at the call site too: initialized scalar, aggregate and SIMD results retain <code>noundef</code>, while <code>Box&lt;T&gt;</code> and reference results retain <code>nonnull noundef</code>. Ownership alone never invents allocator-style return <code>noalias</code>.</p><p>O3 indirect-call promotion is proof-carrying. It consumes only the exact target identities sealed by semantic lowering in standard LLVM <code>!callees</code> metadata; it never guesses candidates by scanning for the same opaque-pointer signature. Without that proof the call stays indirect. Before rewriting, the pass also requires an exact function type, calling convention and ABI-attribute match. Variadic calls, <code>tail</code>/<code>musttail</code>, invokes and unknown call metadata fail closed, while operand bundles, <code>notail</code>, attributes, fast-math flags, debug locations and the indirect fallback are preserved.</p><p>LLVM alias information is emitted only from sealed semantic facts. Alias-scope domains are operation-distinct even after separately compiled modules are linked. TBAA describes the storage actually accessed: pointer slots are pointer storage, whole aggregates and byte views remain conservative, and scalar field identities include the exact nominal owner and generic specialization. Missing owner or layout information removes the optimization claim instead of guessing from a source name.</p><p>Call coercions follow the same rule. Direct calls, function values and Vex source-variadic packing consume the typed HIR coercion plan before physical ABI transport is selected. LLVM bit widths alone never decide a language conversion or signedness; an unsealed conversion fails before IR emission.</p><p>Memory alignment follows pointer provenance as well. A SIMD value&#39;s preferred register/ABI width is not treated as proof that an array or slice address has the same alignment. Generic vector memory operations are conservative; optimized paths publish stronger alignment only from the element type, Vex&#39;s allocator/entry-alloca guarantee, or immutable global storage. This keeps the same source valid on NEON, AVX2 and AVX-512 without sacrificing vectorized O3 code. Allocator-backed closure fields use their exact TargetData offset, while array and Vec stores are bounded by the storage base and element ABI. Repeated SIMD stores also include their byte stride in the proof, so a strongly aligned first address cannot overstate later iterations. Pointer-transported aggregate copies use the destination alloca&#39;s exact guarantee and the source type&#39;s target ABI alignment; no fixed alignment is guessed for closure or contract-default arguments. Program-lifetime <code>invariant.load</code> metadata is likewise restricted to real loads from true constant globals, never ordinary immutable borrows.</p><p>The cooperative async-local allocator is also a proven 16-byte source: its page, bump, size-class and private-header layout preserve that boundary, so its LLVM return declaration publishes the fact directly. Pointer-backed aggregate values are not all equivalent, however. Stack storage, general/async allocation, RC/ARC payloads and user pointers have different guarantees; aggregate copies must carry storage provenance before the compiler strengthens their alignment.</p><p>Runtime function attributes also describe the intersection of all target implementations, not the most favorable backend. Arena and region accessors may release a losing first-use runtime-state allocation, while standard-stream wrappers can cross a libc <code>FILE*</code> boundary on macOS. Those functions therefore keep their proven control-flow facts but do not advertise <code>nofree</code> to LLVM.</p><p>Bounds facts preserve the source integer contract. Signed and unsigned indices are widened differently, and 128-bit indices keep all of their high bits until the bounds decision; the backend never truncates first and then mistakes a wrapped value for a valid address. SIMD chunk loops prove <code>width &lt;= length - index</code> before publishing any no-wrap increment. Thus the check itself remains defined even for adversarial maximum-size inputs, while the guarded hot loop still gives LLVM the strong fact it needs.</p><p>Allocation optimizations use exact LLVM def-use identity rather than pointer names or a search for one direct <code>free</code>. Consecutive allocations may be merged only when every derived use stays local and no derived pointer is freed; zero-size and overflowing size calculations are rejected. Heap-to-stack and SBO promotion share the same rule. Pointer casts and GEPs preserve one root, but PHI/select nodes are not assumed to do so because they may combine distinct allocation lifetimes.</p><p>Heap-to-stack replacement preserves Vex&#39;s 16-byte allocator alignment and never turns a failing zero-size allocation into live stack storage. Coroutine frames additionally require an explicit non-owning wrapper proof; the optimizer does not mutate shared async wrapper or cleanup functions to erase frees.</p><p>Arena-loop hoisting mirrors the runtime&#39;s physical layout. It specializes only exact constant positive loops, preserves signed induction widening, and uses a 16-byte stride per allocation. All trip/span arithmetic is checked, nested allocations belong to the innermost loop, and one batch cannot exceed an ordinary arena chunk. Dynamic or unrepresentable cases retain the original allocator calls.</p><p>Small constant <code>memcpy</code> lowering is equally provenance-aware. Byte-pointer inputs are scalarized only for non-volatile copies and the generated accesses remain conservatively aligned to one byte unless an independent provenance proof strengthens them. Bounds-check reuse requires the exact normalized index and length SSA values plus dominance by a previous successful check; the optimizer never erases aggregate-field identity or signedness casts to invent a shared proof.</p><p>CPU/GPU UMA barrier removal is proof-carrying. A pointer that is only read by the CPU is not enough: the read may follow a GPU write and require coherence. The optimizer removes a barrier only when semantic Valence lowering seals an exact proof covering transition direction, producer completion and the full alias set. Missing proof keeps the barrier live, and exception-capable <code>invoke</code> sites are never rewritten as plain branches.</p><p>Constant string-slice folding preserves the language-level <code>usize</code> domain as well. High-bit indices remain unsigned and clamp to the view length exactly as the runtime operator does; the LLVM folder never reinterprets them as negative signed offsets. Receiver and result layouts are validated before constructing constant pointers or VexStr values.</p><p>SSO concatenation folds only after validating its complete physical result layout. Unknown or stale layouts keep the original call, and pointer payloads retain their declared address space.</p><p>Diverging direct calls terminate in <code>unreachable</code>; pruning their stale normal continuation also repairs successor PHI predecessors before LLVM sees the CFG.</p><p>Inlining uses two levels of evidence. HIR can attach positive hints from typed semantic shape, and a post-lowering budget checks the concrete body after specialization, ownership lowering and Vex-specific simplification. Bodies over the configured instruction ceiling lose only automatic positive hints; the compiler does not turn size into a blanket <code>noinline</code> contract. Explicit source <code>inline fn</code> declarations and genuine semantic/cold boundaries remain authoritative, while LLVM&#39;s target-aware cost model decides otherwise unhinted call sites. Opt-in module profiling reports the top-five body concentration so cold outlining is introduced from measured evidence rather than source size.</p><h3 id="sir-path" tabindex="-1">SIR Path <a class="header-anchor" href="#sir-path" aria-label="Permalink to “SIR Path”">​</a></h3><p>When the program shape is suitable for data-parallel lowering, Vex can form SIR graphs that later target SIMD and selected accelerator backends.</p><p>This path is the basis for:</p><ul><li>vector-style arithmetic</li><li>tensor and mask operations</li><li>fusion and graph rewrites</li><li>backend-specific kernel generation</li></ul><h2 id="driver-layer" tabindex="-1">Driver Layer <a class="header-anchor" href="#driver-layer" aria-label="Permalink to “Driver Layer”">​</a></h2><p>The user usually interacts with the compiler through <code>vex-cli</code>, which wraps compilation, linking, execution, and test discovery.</p><p>That means the operational pipeline is often:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vex run / vex compile / vex test</span></span>
<span class="line"><span>  -&gt; compiler driver</span></span>
<span class="line"><span>  -&gt; embedded VRI selection + semantic fusion</span></span>
<span class="line"><span>  -&gt; explicit target/native link plan</span></span>
<span class="line"><span>  -&gt; execution or test reporting</span></span></code></pre></div><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to “Related Pages”">​</a></h2><ul><li><a href="/docs/architecture/sir-and-backends">SIR &amp; Backends</a></li><li><a href="/docs/architecture/comptime-pipeline">Comptime Pipeline</a></li><li><a href="/docs/architecture/runtime-and-tooling">Runtime &amp; Tooling</a></li><li><a href="/docs/references/vex-cli-reference">CLI Reference</a></li></ul>`,56)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};